var req = new HttpRequest();
req.addHeader("Content-Type: application/json");
try {
    req.post("{$STORWARE.API.URL}/session/login", JSON.stringify({login: "{$STORWARE.USER}", password: "{$STORWARE.PASSWORD}"}));
    if (req.getStatus() !== 200) return -1;
    var response = req.get("{$STORWARE.API.URL}/hypervisor-managers");
    if (req.getStatus() !== 200) return -1;
    var managers = JSON.parse(response);
    var now = Math.floor(Date.now() / 1000);
    var oldest = now;
    for (var i = 0; i < managers.length; i++) {
        var ts = managers[i].lastSuccessfulInventorySyncTimestamp || 0;
        if (ts > 0 && ts < oldest) oldest = ts;
    }
    return ((now - oldest) / 3600).toFixed(1);
} catch(e) { return -1; }

