var req = new HttpRequest();
req.addHeader('Content-Type: application/json');
req.post('{$STORWARE.API.URL}/session/login', JSON.stringify({login: '{$STORWARE.USER}', password: '{$STORWARE.PASSWORD}'}));
var response = req.get('{$STORWARE.API.URL}/backups');
var backups = JSON.parse(response);
var instances = {};
for (var i = 0; i < backups.length; i++) {
    var b = backups[i];
    if (b.protectedEntity && b.protectedEntity.guid) {
        var guid = b.protectedEntity.guid;
        if (!instances[guid]) {
            var entityType = 'unknown';
            if (b.protectedEntity.type) entityType = b.protectedEntity.type.name || b.protectedEntity.type;
            instances[guid] = {
                '{#INSTANCE.GUID}': guid,
                '{#INSTANCE.NAME}': b.protectedEntity.name || guid,
                '{#INSTANCE.TYPE}': entityType
            };
        }
    }
}
var result = [];
for (var key in instances) {
    result.push(instances[key]);
}
return JSON.stringify(result);

